export type ProcedenciaEstructural = 'GENERATED' | 'MACHOTE' | 'SOURCE';

export interface DocumentTemplate {
  /** Identificador canónico == classifier.documentType */
  tipo: string;
  /** Labels alternativos que deben resolver a esta plantilla */
  etiquetas: string[];
  // ── Taxonomía ──
  materia: FamiliaDocumental;
  jurisdiccion: string;
  via: string;
  procedimiento: string;
  subtipo?: string;
  // ── Roles procesales (FASE 6) ──
  rolAutor: RolProcesal;
  rolContraparte: string;
  destinatario: Destinatario;
  /** Regla declarativa de conducto: nunca se infiere desde la autoridad fuente. */
  presentacionPor?: 'ORGANO_RESOLUCION_RECURRIDA';
  objetivoProcesal: string;
  // ── Estructura y voz ──
  /** Estructura de salida esperada, en orden (secciones canónicas únicas) */
  estructura: string[];
  /** Directrices de voz (posición procesal del redactor) */
  voz: string[];
  /** Persona completa para el prompt de generación */
  vozPrompt: string;
  // ── Campos ──
  camposObligatorios: string[];
  camposOpcionales: string[];
  /** Alias de compatibilidad == camposObligatorios */
  campos: string[];
  // ── Fuentes permitidas ──
  fuentesPermitidas: string[];
  // ── Reglas ──
  reglas: string[];
  reglasArgumentacion: string[];
  reglasPrueba: string[];
  reglasFirma: string[];
  reglasAnexos: string[];
  /** Prohibiciones explícitas que llegan íntegras al prompt (FASE 15) */
  prohibiciones: string[];
  /** true = la salida se construye sobre esqueleto GENERATED del template */
  esqueletoDedicado: boolean;
}

export class DocumentRoutingError extends Error {
  readonly code: string;

  constructor(code: string, message: string) {
    super(message);
    this.name = 'DocumentRoutingError';
    this.code = code;
  }
}

