const FIRMA_PARTE = [
  'La firma corresponde EXCLUSIVAMENTE a quien detenta el rolAutor (o su apoderado); nunca a la contraparte ni a la autoridad.',
];
const ANEXOS_BASE = [
  'Enumera solo anexos derivados del expediente o solicitados expresamente; no inventes documentos.',
];

function prohibicionesContestacion(): string[] {
  return [
    ...PROHIBICIONES_BASE,
    'PROHIBIDO usar rúbricas propias de resoluciones judiciales —VISTO, R E S U L T A N D O, RESULTANDO, C O N S I D E R A N D O, CONSIDERANDO, PUNTOS RESOLUTIVOS— cuando provengan exclusivamente de la fuente.',
    'NUNCA atribuyas carácter de parte litigante a la autoridad jurisdiccional: si el nombre del demandado o del actor no consta, usa [DATO PENDIENTE DE EXPEDIENTE: …].',
    'Los fragmentos del expediente son REFERENCIA DE SOLO LECTURA: PROHIBIDO copiarlos textualmente como cuerpo del escrito.',
    'PROHIBIDO redactar como actor, como quejoso o como juzgador: quien habla es el demandado que contesta.',
    'PROHIBIDO copiar el listado/tabla de ROLES PROCESALES dentro del contenido; en COMPARECENCIA y FIRMA interviene únicamente el DEMANDADO que contesta.',
  ];
}

/** Semilla con valores por defecto compartidos; cada entrada aporta lo específico. */
type DefaultableKeys =
  | 'reglasArgumentacion'
  | 'reglasPrueba'
  | 'reglasFirma'
  | 'reglasAnexos'
  | 'fuentesPermitidas'
  | 'prohibiciones'
  | 'esqueletoDedicado'
  | 'camposOpcionales';

type TemplateSeed = Omit<DocumentTemplate, 'campos' | DefaultableKeys> &
  Partial<Pick<DocumentTemplate, DefaultableKeys>> & { campos?: string[] };

function def(seed: TemplateSeed): DocumentTemplate {
  const {
    reglasArgumentacion = [],
    reglasPrueba = [],
    reglasFirma = FIRMA_PARTE,
    reglasAnexos = ANEXOS_BASE,
    fuentesPermitidas = FUENTES_PARTES,
    prohibiciones = PROHIBICIONES_BASE,
    esqueletoDedicado = true,
    camposOpcionales = [],
  } = seed;
  return {
    ...seed,
    camposOpcionales,
    reglasArgumentacion,
    reglasPrueba,
    reglasFirma,
    reglasAnexos,
    fuentesPermitidas,
    prohibiciones,
    esqueletoDedicado,
    campos: seed.campos ?? seed.camposObligatorios,
  };
}

