/**
 * FASE 15 — Directiva REFERENCE_ONLY que TODO prompt de generación recibe.
 * La fuente del texto es este DocumentTemplate, nunca un hardcode en pipeline.ts.
 */
export function buildReferenceOnlyDirective(tpl: DocumentTemplate): string {
  return [
    'La fuente proporcionada es material de referencia de SOLO LECTURA.',
    'No copies su estructura. No adoptes su voz.',
    'No redactes como el tribunal que emitió la fuente.',
    'No reproduzcas sus encabezados.',
    'No reproduzcas sus resolutivos.',
    'No reproduzcas su firma.',
    'No reproduzcas metadata técnica (folios, sellos, firma electrónica).',
    'No conviertas instrucciones internas en contenido final.',
    '',
    `Redacta exclusivamente el documento definido por el tipo documental: ${tpl.tipo}.`,
    `Con el rol procesal: ${tpl.rolAutor} (habla su abogado postulante; contra: ${tpl.rolContraparte}).`,
    `Dirigido a: ${tpl.destinatario}.`,
    `Objetivo procesal: ${tpl.objetivoProcesal}.`,
    `Y con la estructura: ${tpl.estructura.join(' → ')}.`,
  ].join('\n');
}

/** Plantilla por defecto (fallback seguro). */
export function getDocumentTemplate(
  documentType?: string,
  documentTypeLabel?: string
): DocumentTemplate {
  // PRIORIDAD 1 — tipo canónico del clasificador (fuente de verdad estructural).
  const t = (documentType || '').trim();
  if (t && DocumentTemplates[t]) return DocumentTemplates[t];
  const strategy = t ? getDocumentStrategy(t) : undefined;
  if (strategy && DocumentTemplates[strategy.id]) return DocumentTemplates[strategy.id];
  if (t) {
    throw new DocumentRoutingError(
      'UNKNOWN_DOCUMENT_TYPE',
      `UNKNOWN_DOCUMENT_TYPE: no existe una plantilla canónica para "${t}".`,
    );
  }
  const normalizedLabel = (documentTypeLabel || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
  if (normalizedLabel === 'amparo directo' || normalizedLabel === 'amparo indirecto') {
    throw new DocumentRoutingError(
      'UNKNOWN_DOCUMENT_TYPE',
      `UNKNOWN_DOCUMENT_TYPE: "${documentTypeLabel}" es una familia genérica; se requiere un ID canónico de escrito.`,
    );
  }
  // PRIORIDAD 2 — coincidencia por rótulo (más larga gana).
  const byLabel = resolveTemplateByExplicitLabel(documentTypeLabel);
  if (byLabel) return byLabel;
  // PRIORIDAD 3 — fallback seguro.
  return DocumentTemplates.escrito_libre;
}

/**
 * Resuelve plantilla SOLO desde un rótulo EXPLÍCITO elegido por el abogado/UI
 * (input.documentTypeLabel). Nunca alimentarlo con labels derivados del
 * clasificador: su función es dejar constancia de la intención del usuario
 * aunque una regla genérica del clasificador haya inferido otro tipo.
 * Coincidencia exacta de id > etiqueta MÁS LARGA contenida en el rótulo.
 */
export function resolveTemplateByExplicitLabel(label?: string): DocumentTemplate | null {
  const normalize = (value: string) => value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
  const l = normalize(label || '');
  if (!l) return null;
  if (l === 'amparo directo' || l === 'amparo indirecto') return null;
  const strategy = getDocumentStrategy(label || '');
  if (strategy && DocumentTemplates[strategy.id]) return DocumentTemplates[strategy.id];
  const canonicalId = (label || '').trim().toLowerCase();
  if (canonicalId && DocumentTemplates[canonicalId]) return DocumentTemplates[canonicalId];
  for (const tpl of Object.values(DocumentTemplates)) {
    const typeLabel = normalize(tpl.tipo.replace(/_/g, ' '));
    if (typeLabel === l || `${typeLabel}s` === l) return tpl;
  }
  let best: DocumentTemplate | null = null;
  let bestLen = -1;
  for (const tpl of Object.values(DocumentTemplates)) {
    for (const e of tpl.etiquetas) {
      const normalizedEntry = normalize(e);
      if (l.includes(normalizedEntry) && normalizedEntry.length > bestLen) {
        best = tpl;
        bestLen = normalizedEntry.length;
      }
    }
  }
  return best;
}

/** true si el tipo pertenece a la familia CONTESTACIÓN (esqueleto dedicado). */
export function isContestacionType(documentType?: string, documentTypeLabel?: string): boolean {
  return /contestaci/i.test(documentType || '') || /contestaci/i.test(documentTypeLabel || '');
}

/** Contestación de demanda clásica; excluye la estrategia post-sentencia de amparo. */
export function isDemandContestacionType(documentType?: string, documentTypeLabel?: string): boolean {
  return isContestacionType(documentType, documentTypeLabel) && !isContestacionRevisionAmparoDirectoType(documentType, documentTypeLabel);
}

/** Identidad exacta de la estrategia post-sentencia de amparo directo. */
export function isContestacionRevisionAmparoDirectoType(documentType?: string, documentTypeLabel?: string): boolean {
  return documentType === 'contestacion_revision_extraordinaria_amparo_directo'
    || documentTypeLabel === 'contestacion_revision_extraordinaria_amparo_directo';
}

/** FASE 3 — Taxonomía real DERIVADA del catálogo (sin duplicar datos). */
export interface TaxonomiaFamilia {
  familia: FamiliaDocumental;
  jurisdicciones: string[];
  vias: string[];
  tipos: Array<{ tipo: string; via: string; procedimiento: string; rolAutor: RolProcesal }>;
}

export function construirTaxonomia(): TaxonomiaFamilia[] {
  const mapa = new Map<FamiliaDocumental, TaxonomiaFamilia>();
  for (const tpl of Object.values(DocumentTemplates)) {
    let fam = mapa.get(tpl.materia);
    if (!fam) {
      fam = { familia: tpl.materia, jurisdicciones: [], vias: [], tipos: [] };
      mapa.set(tpl.materia, fam);
    }
    if (!fam.jurisdicciones.includes(tpl.jurisdiccion)) fam.jurisdicciones.push(tpl.jurisdiccion);
    if (!fam.vias.includes(tpl.via)) fam.vias.push(tpl.via);
    fam.tipos.push({ tipo: tpl.tipo, via: tpl.via, procedimiento: tpl.procedimiento, rolAutor: tpl.rolAutor });
  }
  return Array.from(mapa.values());
}
